widget.css:
* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; background: transparent; color: rgba(255,255,255,.88); font: 11px -apple-system; }
.widget { width: 100%; height: 100%; padding: 9px 10px; border-radius: 13px; background: rgba(255,255,255,.09); display: flex; flex-direction: column; justify-content: space-between; }
button { border: 0; padding: 0 8px; color: rgba(255,255,255,.62); background: transparent; font: inherit; }

widget.javascript:
const status = document.getElementById('status');
let timer;
function render(result) {
  if (result?.ok) status.textContent = result.state?.summary || '已刷新';
}
async function refresh() {
  const result = await notchany.invoke('refresh', null);
  if (result.ok) render(result); else if (!notchany.state) status.textContent = result.error.message;
}
notchany.addEventListener('visibilitychange', () => {
  clearInterval(timer);
  if (notchany.visible) { refresh(); timer = setInterval(refresh, 1000); }
});
notchany.addEventListener('statechange', event => render(event.state));
if (notchany.state) render(notchany.state);
document.getElementById('refresh').onclick = refresh;
document.getElementById('run').onclick = async () => {
  const result = await notchany.execute('run', null);
  status.textContent = result.ok ? '已执行' : result.error.message;
};
